# ruff: noqa: E501
"""Standalone three-column review workbench served by the Python HTTP adapter."""

from __future__ import annotations

import json


def review_workbench_html(conversion_job_id: str) -> bytes:
    job_json = json.dumps(str(conversion_job_id), ensure_ascii=False)
    html = r'''<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>人工复核工作台 · QRA</title>
<style>
:root{--nav:#122a34;--ink:#18313b;--muted:#6b7f87;--line:#d8e2e6;--bg:#f2f6f7;--card:#fff;--teal:#087b74;--amber:#b66b00;--red:#b43131;--blue:#2563a8}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 system-ui,"Microsoft YaHei",sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer}.top{background:var(--nav);color:white;padding:14px 20px;display:flex;gap:18px;align-items:center;justify-content:space-between}.top h1{font-size:19px;margin:0}.top p{margin:3px 0 0;color:#bdd0d6}.metrics{display:flex;gap:8px;flex-wrap:wrap}.metric{background:#ffffff12;border:1px solid #ffffff25;border-radius:8px;padding:6px 10px}.metric b{display:block}.actions{display:flex;gap:8px;flex-wrap:wrap}.btn{border:1px solid var(--line);background:#fff;color:var(--ink);padding:8px 12px;border-radius:7px;text-decoration:none;display:inline-flex;align-items:center;justify-content:center}.btn.primary{background:var(--teal);border-color:var(--teal);color:#fff}.btn.danger{color:var(--red)}.btn:disabled{opacity:.45;cursor:not-allowed}.toolbar{padding:10px 14px;background:#fff;border-bottom:1px solid var(--line);display:flex;gap:8px;align-items:center;flex-wrap:wrap}.toolbar input,.toolbar select{border:1px solid var(--line);border-radius:7px;padding:8px;background:#fff}.workspace{display:grid;grid-template-columns:minmax(260px,28%) minmax(390px,42%) minmax(300px,30%);height:calc(100vh - 190px);min-height:520px}.column{min-width:0;background:#fff;border-right:1px solid var(--line);overflow:auto}.column:last-child{border-right:0}.column-head{position:sticky;top:0;z-index:3;background:#f8fafb;border-bottom:1px solid var(--line);padding:11px 14px;font-weight:700}.item{width:100%;text-align:left;border:0;border-bottom:1px solid #e9eff1;background:#fff;padding:12px 14px;color:inherit}.item:hover,.item.active{background:#eaf6f4}.item-head{display:flex;justify-content:space-between;gap:8px}.item small{display:block;color:var(--muted);margin-top:4px}.badges{display:flex;gap:5px;flex-wrap:wrap;margin-top:7px}.badge{font-size:12px;padding:2px 6px;border-radius:9px;background:#edf1f3;color:#4c626b}.badge.block{background:#fde7e7;color:var(--red)}.badge.warn{background:#fff0d6;color:var(--amber)}.badge.ok{background:#dcf4eb;color:#087356}.content{padding:14px}.empty{padding:30px;color:var(--muted);text-align:center}.candidate{border:1px solid var(--line);border-radius:10px;padding:13px;margin-bottom:10px}.candidate.proposed{border-color:#3e9993;background:#f2fbfa}.candidate h3{font-size:15px;margin:0 0 6px;display:flex;justify-content:space-between;gap:10px}.value{font-size:20px;font-weight:750;color:#123f4b;word-break:break-word}.meta{color:var(--muted);font-size:12px;margin:6px 0}.candidate .actions{margin-top:10px}.panel{border:1px solid var(--line);border-radius:10px;padding:12px;margin-top:12px}.panel h3{font-size:14px;margin:0 0 10px}.field{margin-bottom:9px}.field label{display:block;font-size:12px;color:var(--muted);margin-bottom:4px}.field input,.field select,.field textarea{width:100%;border:1px solid var(--line);border-radius:7px;padding:8px}.field textarea{min-height:70px;resize:vertical}.evidence-meta{display:grid;grid-template-columns:105px 1fr;gap:7px;border-bottom:1px solid #edf1f3;padding:8px 0}.evidence-meta span{color:var(--muted)}.preview{width:100%;min-height:320px;border:1px solid var(--line);border-radius:8px;background:#f8fafb;object-fit:contain}.preview-text{white-space:pre-wrap;word-break:break-word;background:#f8fafb;border:1px solid var(--line);border-radius:8px;padding:12px;max-height:420px;overflow:auto}.context-wrap{overflow:auto;margin-top:12px}.context-table{border-collapse:collapse;width:100%;font-size:12px}.context-table caption{text-align:left;font-weight:700;margin-bottom:6px}.context-table th,.context-table td{border:1px solid var(--line);padding:6px;text-align:left;white-space:nowrap}.context-table tr.target{background:#fff1c9}.tech-details{margin-top:12px}.tech-details pre{white-space:pre-wrap;word-break:break-word;font-size:11px}.gatebar{position:fixed;left:0;right:0;bottom:0;background:#fff;border-top:1px solid var(--line);box-shadow:0 -4px 16px #20343d12;padding:11px 16px;display:flex;justify-content:space-between;align-items:center;gap:12px;z-index:10}.gate-stats{display:flex;gap:14px;flex-wrap:wrap}.gate-stats b{display:block}.gate-stats span{font-size:12px;color:var(--muted)}dialog{border:0;border-radius:12px;padding:0;width:min(560px,92vw);box-shadow:0 16px 60px #0005}dialog::backdrop{background:#10242eb8}.dialog-body{padding:20px}.dialog-body h2{margin-top:0}.dialog-foot{padding:12px 20px;border-top:1px solid var(--line);display:flex;justify-content:flex-end;gap:8px}.notice{padding:10px;border-radius:8px;background:#eef6fb;color:#245775;margin-bottom:10px}.notice.error{background:#fdeaea;color:var(--red)}.tabs{display:none}.toast{position:fixed;right:18px;bottom:92px;background:#17343e;color:white;border-radius:8px;padding:10px 14px;z-index:30;max-width:420px;display:none}@media(max-width:900px){.metrics{display:none}.tabs{display:flex;padding:8px;background:#fff;border-bottom:1px solid var(--line);gap:6px}.workspace{display:block;height:calc(100vh - 235px)}.column{display:none;height:100%;border-right:0}.column.mobile-active{display:block}.gatebar{align-items:flex-end}.gate-stats{gap:7px}.gate-stats div:nth-child(n+4){display:none}}@media(max-width:540px){.top{align-items:flex-start;flex-wrap:wrap}.top .actions{display:flex;width:100%}.top .actions>*{display:none}.top .actions #projectBack{display:inline-flex}.toolbar{flex-wrap:wrap}.toolbar input{width:100%}.gatebar{padding:8px}.gate-stats{font-size:12px}.btn{padding:7px 9px}}
</style>
</head>
<body>
<header class="top"><div><h1>人工复核工作台</h1><p id="projectLine">正在创建或恢复复核会话…</p></div><div class="metrics" id="topMetrics"></div><div class="actions"><a class="btn" id="projectBack" href="/projects/">返回项目</a><a class="btn" href="/admin/">高级任务</a><button class="btn" id="refreshBtn">刷新</button></div></header>
<div class="toolbar"><input id="search" placeholder="搜索字段、实体或管段" aria-label="搜索复核字段"><select id="statusFilter" aria-label="状态筛选"><option value="">全部状态</option><option value="UNRESOLVED">未处理</option><option value="AUTO_DETERMINISTIC">确定性候选</option><option value="ACCEPTED">已接受</option><option value="OVERRIDDEN">已修改</option><option value="REJECTED">已驳回</option><option value="NOT_APPLICABLE">不适用</option><option value="REEXTRACTION_REQUESTED">待重提取</option></select><select id="problemFilter" aria-label="问题类型筛选"><option value="">全部问题</option><option value="CONFLICT">冲突</option><option value="LOW_CONFIDENCE">低置信度</option><option value="MISSING">缺失</option><option value="UNIT">单位异常</option><option value="PROCESSED">已处理</option><option value="UNPROCESSED">未处理</option></select><select id="criticalityFilter" aria-label="关键程度筛选"><option value="">全部关键程度</option><option value="BLOCKING">阻断</option><option value="REQUIRED">计算必需</option><option value="OPTIONAL">可选</option></select><select id="fieldGroupFilter" aria-label="字段组筛选"><option value="">全部字段组</option></select><select id="sourceFilter" aria-label="来源筛选"><option value="">全部来源</option></select><select id="nodeFilter" aria-label="计算节点筛选"><option value="">全部计算节点</option></select><label><input type="checkbox" id="blockingOnly"> 只看阻断</label><span id="listCount"></span></div>
<nav class="tabs" aria-label="移动端视图"><button class="btn primary" data-tab="items">字段</button><button class="btn" data-tab="candidates">候选</button><button class="btn" data-tab="evidence">证据</button></nav>
<main class="workspace">
<section class="column mobile-active" id="itemsColumn" data-column="items" aria-label="待复核字段列表"><div class="column-head">待复核字段</div><div id="itemList"></div></section>
<section class="column" id="candidatesColumn" data-column="candidates" aria-label="候选值比较"><div class="column-head">候选值比较与业务决定</div><div class="content" id="candidatePane"><div class="empty">请从左侧选择字段</div></div></section>
<aside class="column" id="evidenceColumn" data-column="evidence" aria-label="原始证据"><div class="column-head">原始证据</div><div class="content" id="evidencePane"><div class="empty">请选择候选证据</div></div></aside>
</main>
<footer class="gatebar"><div class="gate-stats" id="gateStats"></div><div class="actions"><button class="btn" id="gateBtn">重新执行门禁</button><button class="btn primary" id="confirmBtn" disabled>确认并创建快照</button></div></footer>
<dialog id="confirmDialog"><div class="dialog-body"><h2>确认不可变输入快照</h2><div class="notice" id="confirmSummary"></div><div class="field"><label for="snapshotName">快照名称</label><input id="snapshotName" maxlength="160"></div><div class="field"><label for="confirmReviewer">确认人</label><input id="confirmReviewer" value="local-reviewer" maxlength="120"></div><div class="field"><label for="confirmReason">确认理由</label><textarea id="confirmReason" maxlength="1000" placeholder="说明复核范围、冲突处理和确认依据"></textarea></div><label><input type="checkbox" id="runAfter" checked> 确认后立即创建计算任务</label><label style="margin-left:12px"><input type="checkbox" id="generateCharts" checked> 生成图表</label></div><div class="dialog-foot"><button class="btn" id="cancelConfirm">取消</button><button class="btn primary" id="submitConfirm">确认、创建快照并计算</button></div></dialog>
<dialog id="resultDialog"><div class="dialog-body"><h2>闭环任务已创建</h2><div class="notice" id="resultStatus">正在读取计算状态…</div><div class="evidence-meta"><span>输入快照</span><b class="mono" id="resultSnapshot"></b></div><div class="evidence-meta"><span>计算任务</span><b class="mono" id="resultRun"></b></div><div class="evidence-meta"><span>M1 闭环</span><b id="resultM1">等待计算完成</b></div></div><div class="dialog-foot"><a class="btn" id="resultProject" href="/projects/">返回项目</a><a class="btn" href="/admin/#runs">高级任务</a><a class="btn primary" id="resultReport" target="_blank" hidden>打开本次筛查报告 ↗</a></div></dialog>
<div class="toast" id="toast" role="status"></div>
<script>
const jobId=__JOB_ID__;const projectId=new URLSearchParams(location.search).get('project_id');const projectUrl=projectId?`/projects/${encodeURIComponent(projectId)}/`:'/projects/';const state={session:null,items:[],selected:null,evidence:null,reextractions:[],confirmation:null,runPoll:null,adminToken:null,tokenPrompt:null};
const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function authHeaders(){const h={'Content-Type':'application/json'},t=state.adminToken;if(t)h['X-QRA-Admin-Token']=t;return h}
async function api(path,options={}){const attempted=options._tokenAttempted,requestOptions={...options};delete requestOptions._tokenAttempted;const response=await fetch(path,{...requestOptions,headers:{...authHeaders(),...(options.headers||{})}});let data={};try{data=await response.json()}catch(e){}if(response.status===403&&!attempted){if(!state.tokenPrompt)state.tokenPrompt=Promise.resolve(prompt('请输入管理访问令牌；令牌仅保留在当前页面内存中：',''));const supplied=await state.tokenPrompt;state.tokenPrompt=null;if(supplied){state.adminToken=supplied;return api(path,{...options,_tokenAttempted:true})}}if(response.status===409){await refresh();throw new Error('会话已更新，页面已刷新，请重新确认操作')}if(!response.ok)throw new Error(data.message||data.error||`请求失败 (${response.status})`);return data}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.style.background=error?'#8f2828':'#17343e';el.style.display='block';setTimeout(()=>el.style.display='none',3500)}
function showTab(name){document.querySelectorAll('[data-column]').forEach(el=>el.classList.toggle('mobile-active',el.dataset.column===name));document.querySelectorAll('[data-tab]').forEach(el=>el.classList.toggle('primary',el.dataset.tab===name))}
async function boot(){try{const result=await api(`/admin/api/conversions/${encodeURIComponent(jobId)}/review-sessions`,{method:'POST',body:JSON.stringify({actor:'local-reviewer'})});state.session=result.session;await refresh()}catch(e){$('#projectLine').textContent=e.message;toast(e.message,true)}}
function setFacet(id,label,entries){const select=$(id),current=select.value;select.replaceChildren(new Option(label,''));entries.forEach(([value,text])=>select.add(new Option(text,value)));if([...select.options].some(option=>option.value===current))select.value=current}
function applyFacets(items){const groups=[...new Set(items.map(item=>item.field_group).filter(Boolean))].sort().map(value=>[value,value]);const nodes=[...new Set(items.flatMap(item=>item.affected_node_ids||[]))].sort().map(value=>[value,value]);const sourceMap=new Map();items.forEach(item=>(item.candidates||[]).forEach(candidate=>(candidate.evidence||[]).forEach(evidence=>{const id=String(evidence.location?.file_id||'');if(id)sourceMap.set(id,evidence.source?.file_name||id)})));setFacet('#fieldGroupFilter','全部字段组',groups);setFacet('#nodeFilter','全部计算节点',nodes);setFacet('#sourceFilter','全部来源',[...sourceMap.entries()].sort((a,b)=>String(a[1]).localeCompare(String(b[1]),'zh-CN')))}
function clientFiltered(items){const problem=$('#problemFilter').value,criticality=$('#criticalityFilter').value,group=$('#fieldGroupFilter').value,source=$('#sourceFilter').value,node=$('#nodeFilter').value;return items.filter(item=>(!group||item.field_group===group)&&(!node||(item.affected_node_ids||[]).includes(node))&&(!criticality||(criticality==='BLOCKING'&&item.blocking)||(criticality==='REQUIRED'&&item.required)||(criticality==='OPTIONAL'&&!item.required&&!item.blocking))&&(!source||(item.candidates||[]).some(candidate=>(candidate.evidence||[]).some(evidence=>String(evidence.location?.file_id||'')===source)))&&(!problem||(problem==='CONFLICT'&&item.conflict)||(problem==='LOW_CONFIDENCE'&&item.low_confidence)||(problem==='MISSING'&&item.missing)||(problem==='UNIT'&&(item.issue_codes||[]).some(code=>String(code).includes('UNIT')))||(problem==='PROCESSED'&&!item.requires_resolution)||(problem==='UNPROCESSED'&&item.requires_resolution)))}
async function refresh(){state.session=await api(`/admin/api/review-sessions/${encodeURIComponent(state.session.id)}`);state.reextractions=await api(`/admin/api/review-sessions/${encodeURIComponent(state.session.id)}/reextractions`);const params=new URLSearchParams({limit:'500'});const q=$('#search').value.trim(),status=$('#statusFilter').value;if(q)params.set('q',q);if(status)params.set('status',status);if($('#blockingOnly').checked)params.set('blocking','true');const result=await api(`/admin/api/review-sessions/${encodeURIComponent(state.session.id)}/items?${params}`);applyFacets(result.items);state.items=clientFiltered(result.items);renderHeader();renderItems();const retained=state.selected&&state.items.find(i=>i.review_item_key===state.selected.review_item_key);if(retained)selectItem(retained);else if(state.items.length)selectItem(state.items[0]);else{$('#candidatePane').innerHTML='<div class="empty">筛选条件下没有复核项</div>'}renderGate()}
function renderHeader(){const s=state.session,p=s.progress||{},active=state.reextractions.filter(r=>['QUEUED','RUNNING'].includes(r.status)),latest=state.reextractions[0],remaining=p.unresolved||0;$('#projectLine').textContent=`${s.project_name||'未命名项目'} · 距确认还需处理 ${remaining} 项${latest?' · 最近重提取 '+latest.status:''}`;$('#topMetrics').innerHTML=[['状态',s.status],['已处理',`${p.resolved||0}/${p.total||0}`],['待确认',remaining],['重提取',active.length?`${active.length} 运行中`:(latest?.status||'无')],['目标节点',(s.target_node_ids||[]).length]].map(([a,b])=>`<div class="metric"><span>${esc(a)}</span><b>${esc(b)}</b></div>`).join('')}
function renderItems(){const list=$('#itemList');list.replaceChildren();$('#listCount').textContent=`${state.items.length} 项`;if(!state.items.length){list.innerHTML='<div class="empty">没有匹配字段</div>';return}state.items.forEach(item=>{const b=document.createElement('button');b.className='item'+(state.selected?.review_item_key===item.review_item_key?' active':'');b.type='button';const flags=[item.blocking?'<span class="badge block">阻断</span>':'',item.conflict?'<span class="badge warn">冲突</span>':'',item.low_confidence?'<span class="badge warn">低置信度</span>':'',item.missing?'<span class="badge block">缺失</span>':'',`<span class="badge ${item.requires_resolution?'':'ok'}">${esc(item.resolution_status)}</span>`].join('');b.innerHTML=`<div class="item-head"><b>${esc(item.field_name)}</b><span>${Math.round(item.highest_confidence*100)}%</span></div><small>${esc(item.entity_id)} · ${item.candidate_count} 候选 / ${item.evidence_count} 证据</small><div class="badges">${flags}</div>`;b.addEventListener('click',()=>selectItem(item));list.append(b)})}
function valueText(v){return typeof v==='object'?JSON.stringify(v):String(v??'—')}
function selectItem(item){state.selected=item;renderItems();renderCandidatePane();if(window.innerWidth<=900)showTab('candidates')}
function renderCandidatePane(){const item=state.selected,pane=$('#candidatePane');if(!item)return;const def=item.field_definition||{},candidates=item.candidates||[],criticality=item.blocking?'阻断':item.required?'计算必需':'可选',nodes=(item.affected_node_ids||[]).join('、')||'不直接阻断节点';pane.innerHTML=`<div><h2 style="margin:0 0 3px;font-size:18px">${esc(item.field_name)}</h2><div class="meta">${esc(item.field_id)} · ${esc(item.entity_id)} · 类型 ${esc(def.value_type||'—')} · 标准单位 ${esc(def.canonical_unit||'无')}</div><div class="badges"><span class="badge ${item.blocking?'block':item.required?'warn':'ok'}">${esc(criticality)}</span><span class="badge">数据层：项目事实</span><span class="badge">影响：${esc(nodes)}</span></div><div class="notice">计算参数包由系统按版本受控绑定；这里仅复核项目事实，不会覆盖模型参数。</div>${item.issue_codes.length?`<div class="notice ${item.blocking?'error':''}">${item.issue_codes.map(esc).join(' · ')}</div>`:''}</div><div id="candidateCards"></div><div class="panel"><h3>业务操作</h3><div class="field"><label>复核人</label><input id="decisionActor" value="local-reviewer" maxlength="120"></div><div class="field"><label>确认原因（必填）</label><textarea id="decisionReason" maxlength="1000"></textarea></div><div id="manualEditor"></div><div class="actions"><button class="btn" id="overrideBtn">保存手工修改</button><button class="btn danger" id="rejectBtn">驳回全部</button>${item.available_actions.includes('MARK_NOT_APPLICABLE')?'<button class="btn" id="naBtn">标记不适用</button>':''}<button class="btn" id="reextractBtn">请求重新提取</button></div></div>`;const cards=$('#candidateCards');if(!candidates.length)cards.innerHTML='<div class="empty">没有候选，可通过手工修改补充或请求重新提取</div>';candidates.forEach(c=>{const card=document.createElement('article');card.className='candidate'+(c.candidate_id===item.proposed_candidate_id?' proposed':'');const source=(c.evidence?.[0]?.source)||{},loc=(c.evidence?.[0]?.location)||{};card.innerHTML=`<h3><span>${c.candidate_id===item.proposed_candidate_id?'系统建议（仍需人工决定）':'候选值'}</span><span>${Math.round(Number(c.confidence||0)*100)}%</span></h3><div class="value">${esc(valueText(c.normalized_value))} ${esc(c.canonical_unit||'')}</div><div class="meta">原值 ${esc(valueText(c.raw_value))} ${esc(c.source_unit||'')} · ${esc(c.extraction_method)} · ${esc(source.file_name||'来源未登记')} · ${esc(loc.sheet_name||loc.page_number||'')} </div><div class="actions"><button class="btn primary" data-accept="${esc(c.candidate_id)}">接受此候选</button>${(c.evidence||[]).map(e=>`<button class="btn" data-evidence="${esc(e.evidence_id)}">查看证据</button>`).join('')}</div>`;cards.append(card)});renderManualEditor(def);pane.querySelectorAll('[data-accept]').forEach(b=>b.addEventListener('click',()=>submitDecision('ACCEPT_CANDIDATE',{selected_candidate_id:b.dataset.accept})));pane.querySelectorAll('[data-evidence]').forEach(b=>b.addEventListener('click',()=>loadEvidence(b.dataset.evidence)));$('#overrideBtn').onclick=()=>{let value=readManualValue(def);submitDecision('OVERRIDE_VALUE',{override_value:value,override_unit:$('#manualUnit')?.value||null})};$('#rejectBtn').onclick=()=>submitDecision('REJECT_ALL',{});if($('#naBtn'))$('#naBtn').onclick=()=>submitDecision('MARK_NOT_APPLICABLE',{});$('#reextractBtn').onclick=()=>{const first=item.candidates?.[0]?.evidence?.[0]||{};submitDecision('REQUEST_REEXTRACTION',{source_id:first.location?.file_id||null,evidence_id:first.evidence_id||null})}}
function renderManualEditor(def){const host=$('#manualEditor'),type=def.value_type||'string',constraints=def.constraints||{};let control;if(type==='enum'){control=`<select id="manualValue">${(constraints.enum||[]).map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select>`}else if(type==='boolean'){control='<select id="manualValue"><option value="true">是 / true</option><option value="false">否 / false</option></select>'}else if(type==='number'||type==='integer'){control=`<input id="manualValue" type="number" ${type==='integer'?'step="1"':'step="any"'}>`}else if(type==='date'){control='<input id="manualValue" type="date">'}else if(['object','array'].includes(type)){control='<textarea id="manualValue" placeholder="请输入符合字段类型的 JSON"></textarea>'}else{control='<input id="manualValue" type="text">'}host.innerHTML=`<div class="field"><label>手工值（${esc(type)}）</label>${control}</div>${def.canonical_unit?`<div class="field"><label>输入单位</label><input id="manualUnit" value="${esc(def.canonical_unit)}"></div>`:''}`}
function readManualValue(def){const raw=$('#manualValue').value,type=def.value_type||'string';if(type==='number')return Number(raw);if(type==='integer')return Number.parseInt(raw,10);if(type==='boolean')return raw==='true';if(['object','array'].includes(type))return JSON.parse(raw);return raw}
async function submitDecision(action,extra){const reason=$('#decisionReason').value.trim(),actor=$('#decisionActor').value.trim();if(!reason){toast('请先填写确认原因',true);$('#decisionReason').focus();return}try{const result=await api(`/admin/api/review-sessions/${encodeURIComponent(state.session.id)}/decisions`,{method:'POST',body:JSON.stringify({review_item_key:state.selected.review_item_key,action,reason,actor,expected_revision:state.session.revision,...extra})});toast(result.reextraction_request_id?'重提取已排队，可在顶部查看状态':'复核决定已保存');await refresh();if(result.reextraction_request_id)setTimeout(()=>refresh().catch(()=>{}),1500)}catch(e){toast(e.message,true)}}
function renderTableContext(pane,e,context){const rows=context.rows||[];if(rows.length){const wrap=document.createElement('div');wrap.className='context-wrap';const table=document.createElement('table');table.className='context-table';const caption=document.createElement('caption');caption.textContent=`${e.sheet_name||'表格'} · 目标位置 ${e.cell_range||'—'} · 相邻上下文`;table.append(caption);const body=document.createElement('tbody');rows.forEach(item=>{const tr=document.createElement('tr');if(String(e.cell_range||'').startsWith(`R${item.row}C`))tr.className='target';const head=document.createElement('th');head.scope='row';head.textContent=`第 ${item.row} 行`;tr.append(head);(item.values||[]).forEach(value=>{const td=document.createElement('td');td.textContent=value==null?'':String(value);tr.append(td)});body.append(tr)});table.append(body);wrap.append(table);pane.append(wrap)}else{const note=document.createElement('p');note.className='notice';note.textContent=e.original_text?`证据原文：${e.original_text}`:'该格式使用稳定结构位置定位，当前无可展示的表格上下文。';pane.append(note)}const details=document.createElement('details');details.className='tech-details';const summary=document.createElement('summary');summary.textContent='技术追溯信息';const pre=document.createElement('pre');pre.textContent=JSON.stringify({location:e.location,model_or_rule_versions:e.model_or_rule_versions,source_quality:e.source_quality},null,2);details.append(summary,pre);pane.append(details)}
async function loadEvidence(id){try{const e=await api(`/admin/api/review-sessions/${encodeURIComponent(state.session.id)}/evidence/${encodeURIComponent(id)}`);state.evidence=e;const pane=$('#evidencePane');pane.replaceChildren();const title=document.createElement('h2');title.style.cssText='font-size:17px;margin-top:0';title.textContent=e.sanitized_file_name||'原始证据';pane.append(title);const versionText=e.model_version||Object.values(e.model_or_rule_versions||{}).join(' / ')||'—';const pairs=[['证据编号',e.evidence_id],['文件 SHA-256',e.sha256],['位置',e.cell_range||e.page_number||'结构位置'],['工作表',e.sheet_name||'—'],['解析器',`${e.parser_id||'—'} / ${e.parser_version||'—'}`],['提取方式',e.extraction_method],['模型/规则版本',versionText],['提示词版本',e.prompt_version||'—'],['置信度',e.confidence],['原始文本',e.original_text||'—']];pairs.forEach(([a,b])=>{const row=document.createElement('div');row.className='evidence-meta';const l=document.createElement('span');l.textContent=a;const v=document.createElement('b');v.textContent=String(b??'—');row.append(l,v);pane.append(row)});const visual=e.media_type==='application/pdf'||e.media_type?.startsWith('image/');if(visual){const preview=document.createElement('img');preview.className='preview';preview.alt=`${e.sanitized_file_name||'证据'}高亮预览`;preview.src=e.preview_url;pane.append(preview)}else{const response=await fetch(e.preview_url,{headers:authHeaders()});const context=await response.json();renderTableContext(pane,e,context)}if(window.innerWidth<=900)showTab('evidence')}catch(err){toast(err.message,true)}}
function renderGate(){const g=state.session.gate_summary||{},p=state.session.progress||{};$('#gateStats').innerHTML=[['已处理',p.resolved||0],['未处理',p.unresolved||0],['阻断',g.blocking_issue_count??'—'],['警告',g.warning_count??'—'],['写入字段',g.assembled_field_count??'—'],['可运行节点',(g.runnable_node_ids||[]).length],['跳过节点',(g.skipped_node_ids||[]).length]].map(([a,b])=>`<div><b>${esc(b)}</b><span>${esc(a)}</span></div>`).join('');$('#confirmBtn').disabled=!(g.status==='PASS'&&state.session.status==='READY_TO_CONFIRM')}
async function runGate(){try{const result=await api(`/admin/api/review-sessions/${encodeURIComponent(state.session.id)}/gate`,{method:'POST',body:JSON.stringify({actor:'local-reviewer'})});toast(result.status==='PASS'?'质量门禁通过':'门禁仍有阻断项',result.status!=='PASS');await refresh()}catch(e){toast(e.message,true)}}
function openConfirm(){const g=state.session.gate_summary;if(!g||g.status!=='PASS')return;$('#snapshotName').value=state.session.project_name||'人工复核输入快照';$('#confirmSummary').textContent=`候选 ${String(state.session.candidate_set_hash).slice(0,12)}… · 决定 ${String(state.session.decision_set_hash).slice(0,12)}… · ${g.assembled_field_count} 个字段 · ${(g.runnable_node_ids||[]).length} 个可运行节点`;$('#confirmDialog').showModal()}
async function pollConfirmedRun(){if(!state.confirmation?.run_id)return true;try{const details=await api(`/admin/api/runs/${encodeURIComponent(state.confirmation.run_id)}`),status=details.run.status;$('#resultStatus').textContent=`计算状态：${status}`;if(status==='COMPLETED'){clearInterval(state.runPoll);state.runPoll=null;const summary=await api(`/admin/api/conversions/${encodeURIComponent(jobId)}/m1-summary?review_session_id=${encodeURIComponent(state.session.id)}&run_id=${encodeURIComponent(state.confirmation.run_id)}`);$('#resultM1').textContent=summary.status;$('#resultReport').href=`/runs/${encodeURIComponent(state.confirmation.run_id)}/`;$('#resultReport').hidden=false;return true}else if(status==='FAILED'){clearInterval(state.runPoll);state.runPoll=null;$('#resultM1').textContent='FAILED';return true}}catch(e){$('#resultStatus').textContent=e.message}return false}
async function confirmSnapshot(){const body={snapshot_name:$('#snapshotName').value.trim(),reviewer:$('#confirmReviewer').value.trim(),reason:$('#confirmReason').value.trim(),expected_revision:state.session.revision,expected_candidate_set_hash:state.session.candidate_set_hash,expected_decision_set_hash:state.session.decision_set_hash,run_after_confirm:$('#runAfter').checked,generate_charts:$('#generateCharts').checked};try{const result=await api(`/admin/api/review-sessions/${encodeURIComponent(state.session.id)}/confirm`,{method:'POST',body:JSON.stringify(body)});state.confirmation=result;$('#confirmDialog').close();$('#resultSnapshot').textContent=result.snapshot_id;$('#resultRun').textContent=result.run_id||'未创建';$('#resultStatus').textContent=result.run_id?'计算状态：QUEUED':'快照已创建，未启动计算';$('#resultDialog').showModal();toast('不可变快照与计算任务已创建');if(result.run_id&&!(await pollConfirmedRun()))state.runPoll=setInterval(pollConfirmedRun,1200)}catch(e){toast(e.message,true)}}
$('#projectBack').href=projectUrl;$('#resultProject').href=projectUrl;$('#refreshBtn').onclick=()=>refresh().catch(e=>toast(e.message,true));$('#gateBtn').onclick=runGate;$('#confirmBtn').onclick=openConfirm;$('#cancelConfirm').onclick=()=>$('#confirmDialog').close();$('#submitConfirm').onclick=confirmSnapshot;$('#search').addEventListener('input',()=>refresh().catch(()=>{}));['#statusFilter','#problemFilter','#criticalityFilter','#fieldGroupFilter','#sourceFilter','#nodeFilter'].forEach(id=>$(id).onchange=()=>refresh());$('#blockingOnly').onchange=()=>refresh();document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>showTab(b.dataset.tab));boot();
</script>
</body></html>'''.replace("__JOB_ID__", job_json)
